jid=$(sbatch --parsable "sweeps/E2-protocolB/B-cex-single-median-levir-s44.sh") && echo "sweeps/E2-protocolB/B-cex-single-median-levir-s44.sh -> job $jid"
jid=$(sbatch --parsable "sweeps/E2-protocolB/B-cex-difference-median-levir-s42.sh") && echo "sweeps/E2-protocolB/B-cex-difference-median-levir-s42.sh -> job $jid"
jid=$(sbatch --parsable "sweeps/E2-protocolB/B-cex-difference-median-levir-s43.sh") && echo "sweeps/E2-protocolB/B-cex-difference-median-levir-s43.sh -> job $jid"
jid=$(sbatch --parsable "sweeps/E2-protocolB/B-cex-difference-median-levir-s44.sh") && echo "sweeps/E2-protocolB/B-cex-difference-median-levir-s44.sh -> job $jid"
